def _implementation(config: DataConnectorConfig) -> DataConnectorImplementation:
    if config.implementation is None:
        raise ValueError(f"data connector '{config.name}' has no implementation")
    return DataConnectorImplementation(config.implementation)


def _http_data_connector(config: DataConnectorConfig) -> HttpDataConnectorConfig:
    return HttpDataConnectorConfig(
        id=config.id,
        name=config.name,
        implementation=_implementation(config),
        host=config.host,
        port=config.port,
        module=config.module,
        use_dedicated_listener=config.use_dedicated_listener or False,
        properties=config.properties,
    )


def _grpc_data_connector(config: DataConnectorConfig) -> GrpcDataConnectorConfig:
    return GrpcDataConnectorConfig(
        id=config.id,
        name=config.name,
        implementation=_implementation(config),
        address=config.address,
        module=config.module,
        connections_count=config.connections_count or 1,
        properties=config.properties,
    )


def _kafka_data_connector(config: DataConnectorConfig) -> KafkaDataConnectorConfig:
    return KafkaDataConnectorConfig(
        id=config.id,
        name=config.name,
        implementation=_implementation(config),
        brokers=config.brokers,
        version=config.version,
        dial_timeout=config.dial_timeout or 0.0,
        use_partitioner=config.use_partitioner or False,
        async_=getattr(config, "async_", False) or False,
        security_protocol=config.security_protocol or KafkaSecurityProtocol.PLAINTEXT,
        sasl_mechanism=config.sasl_mechanism or KafkaSaslMechanism.PLAIN,
        username=config.username,
        password=config.password,
        properties=config.properties,
    )


